"""Drive the real historical compiler and writer; no generated bytes are edited."""

import pathlib
import subprocess
import sys
import tempfile


def project(root):
    (root / "src").mkdir()
    (root / "Nargo.toml").write_text(
        '[package]\nname = "identity"\ntype = "bin"\nauthors = []\n'
    )
    (root / "src/main.nr").write_text(
        "unconstrained fn main() { let x: u32 = 42; println(x); assert(x == 42); }\n"
    )
    (root / "Prover.toml").write_text("")


def trace(root, recording_id=None, workdir="/fixtures/identity"):
    command = [sys.argv[1], "trace", "--out-dir", "out"]
    if recording_id is not None:
        command += ["--recording-id", recording_id, "--recording-workdir", workdir]
    subprocess.run(command, cwd=root, check=True)
    return (root / "out/identity.ct").read_bytes()


with tempfile.TemporaryDirectory() as first, tempfile.TemporaryDirectory() as second:
    a, b = pathlib.Path(first), pathlib.Path(second)
    project(a)
    project(b)
    identity = "01949fcc-7d92-7e9c-8000-000000000001"
    baseline = trace(a, identity)
    assert baseline == trace(b, identity), "recordings depend on the source directory"
    assert baseline != trace(a, "01949fcc-7d92-7e9c-8000-000000000002"), "id ignored"
    assert baseline != trace(a, identity, "/fixtures/another"), "workdir ignored"
    assert trace(a) != trace(a), "default recordings must mint independent identities"

    # Invalid identities must fail before any container is created.
    (a / "out/identity.ct").unlink()
    invalid = subprocess.run(
        [sys.argv[1], "trace", "--out-dir", "out", "--recording-id", "invalid"],
        cwd=a, capture_output=True, text=True,
    )
    assert invalid.returncode != 0 and "recording id" in invalid.stderr, invalid.stderr
    assert not (a / "out/identity.ct").exists(), "invalid id emitted a partial container"

print("fixture recorder: deterministic bytes, identity and workdir controls passed")
